steps_json:
[
    {
        "title": "认识三个内角",
        "description": "任意三角形都有三个内角，分别记作 $\\angle A$、$\\angle B$、$\\angle C$。",
        "bubbleText": "小朋友，你看三角形里有三个角，它们都住在三角形内部，叫做内角哦！",
        "bubblePos": {
            "x": 320,
            "y": 320
        }
    },
    {
        "title": "画辅助平行线",
        "description": "过顶点 $A$ 作直线 $DE$，使 $DE \\parallel BC$。",
        "bubbleText": "老师从 A 点画一条和底边 BC 平行的虚线，它是我们的秘密武器！",
        "bubblePos": {
            "x": 320,
            "y": 130
        }
    },
    {
        "title": "第一组内错角",
        "description": "因为 $DE \\parallel BC$，$AB$ 为截线，所以内错角相等：$\\angle DAB = \\angle ABC$。",
        "bubbleText": "看，左边的角 ∠B' 和下面的 ∠B 是内错角，它们大小一模一样！",
        "bubblePos": {
            "x": 270,
            "y": 170
        }
    },
    {
        "title": "第二组内错角",
        "description": "同理，$AC$ 为截线，另一组内错角相等：$\\angle EAC = \\angle ACB$。",
        "bubbleText": "右边的角 ∠C' 也和下面的 ∠C 相等，这是第二组内错角。",
        "bubblePos": {
            "x": 370,
            "y": 170
        }
    },
    {
        "title": "拼成平角",
        "description": "三个角在直线 $DE$ 上依次排列，组成一个平角：$\\angle DAE = 180^\\circ$。",
        "bubbleText": "三个角排成一排，正好组成一个平角，平角就是 180°！",
        "bubblePos": {
            "x": 320,
            "y": 110
        }
    },
    {
        "title": "推导内角和公式",
        "description": "把内错角替换回去，得到：$\\angle A + \\angle B + \\angle C = 180^\\circ$。",
        "bubbleText": "把 ∠B' 换回 ∠B，把 ∠C' 换回 ∠C，三角形内角和公式就出现啦！",
        "bubblePos": {
            "x": 320,
            "y": 500
        }
    },
    {
        "title": "数字验证",
        "description": "验证：$50^\\circ + 60^\\circ + 70^\\circ = 180^\\circ$，任意三角形内角和都是 $180^\\circ$。",
        "bubbleText": "随便拿一个三角形，50° + 60° + 70° = 180°，答案正确，牢记心中！",
        "bubblePos": {
            "x": 580,
            "y": 330
        }
    }
]
